//! The node configuration file (ADR 0016): one serde struct, generated by the Nix module,
//! never hand-written. No secret in the file: only `private_key_file`.
//!
//! v0.5 schema: `[node]`, `[[peers]]` with `allow_inbound`, `[[lighthouses]]` and
//! `[[relays]]` (at most one each in v0, ADR 0012, 0014), `[firewall]`, `[log]`, and the
//! optional `[metrics]` (ADR 0019, amended 2026-10-20).
//!
//! The lighthouse file ([`LighthouseConfig`]) is `[service]`, `[[peers]]` with `name` and
//! `public_key` only, `[log]` and `[metrics]` (ADR 0016). The relay file ([`RelayConfig`]) is
//! the same, its `[service]` adding the optional per-sender rate limit (ADR 0014, 0031).

use std::collections::HashSet;
use std::net::{IpAddr, SocketAddr};
use std::path::PathBuf;

use kekkai_core::firewall::{Rule, UDP_FLOWS_MAX};
use kekkai_core::keys::{PublicKey, public_key_from_text};
use serde::Deserialize;

/// Default path of the node file (ADR 0016, 0026).
pub const DEFAULT_PATH: &str = "/etc/kekkai/node.toml";
/// Default path of the lighthouse file.
pub const LIGHTHOUSE_DEFAULT_PATH: &str = "/etc/kekkai/lighthouse.toml";
/// Default path of the relay file.
pub const RELAY_DEFAULT_PATH: &str = "/etc/kekkai/relay.toml";
/// Default lighthouse UDP port (ADR 0005).
pub const DEFAULT_LIGHTHOUSE_PORT: u16 = 4800;
/// Default relay UDP port (ADR 0005).
pub const DEFAULT_RELAY_PORT: u16 = 4801;
/// Default node UDP port (ADR 0005).
pub const DEFAULT_LISTEN_PORT: u16 = 4802;
/// Smallest `node.mtu` accepted: the IPv4 minimum reassembly size.
pub const MIN_MTU: u16 = 576;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NodeConfig {
    pub node: NodeSection,
    #[serde(default)]
    pub peers: Vec<PeerSection>,
    #[serde(default)]
    pub lighthouses: Vec<LighthouseSection>,
    #[serde(default)]
    pub relays: Vec<RelaySection>,
    #[serde(default)]
    pub firewall: FirewallSection,
    #[serde(default)]
    pub log: LogSection,
    /// Absent: no metrics listener.
    pub metrics: Option<MetricsSection>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MetricsSection {
    /// `127.0.0.1:PORT` or `[::1]:PORT`: loopback only, the local agent is the only scraper.
    pub listen: SocketAddr,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NodeSection {
    pub private_key_file: PathBuf,
    #[serde(default = "default_listen_port")]
    pub listen_port: u16,
    /// `/32` and `/128` only (ADR 0010).
    pub addresses: Vec<String>,
    /// Default and maximum 1280, lower only (ADR 0009).
    #[serde(default = "default_mtu")]
    pub mtu: u16,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PeerSection {
    pub name: String,
    pub public_key: String,
    pub addresses: Vec<String>,
    /// Static `host:port` endpoints, optional; DNS names are resolved at start.
    #[serde(default)]
    pub endpoints: Vec<String>,
    /// `proto/port` rules (`tcp/22`, `udp/53`, `tcp/*`, `any`) this peer may reach on the
    /// node; default deny except ICMP and replies (ADR 0011).
    #[serde(default)]
    pub allow_inbound: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LighthouseSection {
    pub public_key: String,
    /// `host:port`; a DNS name is resolved at start.
    pub endpoint: String,
}

/// A `[[relays]]` entry: the same fields as a lighthouse's.
pub type RelaySection = LighthouseSection;

impl LighthouseSection {
    pub fn key(&self) -> Result<PublicKey, String> {
        public_key_from_text(&self.public_key)
            .ok_or_else(|| "lighthouse or relay public_key is not a base64 32-byte key".to_string())
    }
}

/// The lighthouse's file.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LighthouseConfig {
    pub service: ServiceSection,
    #[serde(default)]
    pub peers: Vec<NamedKey>,
    #[serde(default)]
    pub log: LogSection,
    pub metrics: Option<MetricsSection>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ServiceSection {
    pub private_key_file: PathBuf,
    #[serde(default = "default_lighthouse_port")]
    pub listen_port: u16,
}

/// A `[[peers]]` entry of the lighthouse: the key it accepts, and a name for status.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NamedKey {
    pub name: String,
    pub public_key: String,
}

fn default_lighthouse_port() -> u16 {
    DEFAULT_LIGHTHOUSE_PORT
}

fn default_relay_port() -> u16 {
    DEFAULT_RELAY_PORT
}

impl LighthouseConfig {
    /// Parses and validates a lighthouse file: what `kekkai-lighthouse config check` runs.
    pub fn parse(text: &str) -> Result<Self, String> {
        refuse_inline_secret(text, "service.private_key_file")?;
        let config: Self = toml::from_str(text).map_err(|e| e.to_string())?;
        if config.service.listen_port == 0 {
            return Err("service.listen_port must not be 0".into());
        }
        check_metrics(&config.metrics)?;
        check_named(&config.peers)?;
        Ok(config)
    }
}

/// The relay's file (ADR 0014, 0016, 0031).
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RelayConfig {
    pub service: RelayServiceSection,
    #[serde(default)]
    pub peers: Vec<NamedKey>,
    #[serde(default)]
    pub log: LogSection,
    pub metrics: Option<MetricsSection>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RelayServiceSection {
    pub private_key_file: PathBuf,
    #[serde(default = "default_relay_port")]
    pub listen_port: u16,
    /// Most `relay_forward` payload bytes per second forwarded for one sender, with one
    /// second's worth as burst (spec §14.2); absent: no limit (ADR 0014).
    pub max_bytes_per_second: Option<u64>,
}

impl RelayConfig {
    /// Parses and validates a relay file: what `kekkai-relay config check` runs.
    pub fn parse(text: &str) -> Result<Self, String> {
        refuse_inline_secret(text, "service.private_key_file")?;
        let config: Self = toml::from_str(text).map_err(|e| e.to_string())?;
        if config.service.listen_port == 0 {
            return Err("service.listen_port must not be 0".into());
        }
        if config.service.max_bytes_per_second == Some(0) {
            return Err("service.max_bytes_per_second must not be 0 (omit it for no limit)".into());
        }
        check_metrics(&config.metrics)?;
        check_named(&config.peers)?;
        Ok(config)
    }
}

/// Lighthouse and relay `[[peers]]`: names and keys unique and well-formed.
fn check_named(peers: &[NamedKey]) -> Result<(), String> {
    let mut keys = HashSet::new();
    let mut names = HashSet::new();
    for peer in peers {
        if peer.name.is_empty() || !names.insert(peer.name.as_str()) {
            return Err(format!("peer name `{}` is empty or repeated", peer.name));
        }
        if !keys.insert(peer.key()?) {
            return Err(format!("peer {}: public key repeated", peer.name));
        }
    }
    Ok(())
}

impl NamedKey {
    pub fn key(&self) -> Result<PublicKey, String> {
        public_key_from_text(&self.public_key)
            .ok_or_else(|| format!("peer {}: public_key is not a base64 32-byte key", self.name))
    }
}

fn refuse_inline_secret(text: &str, field: &str) -> Result<(), String> {
    let table: toml::Table = toml::from_str(text).map_err(|e| e.to_string())?;
    match inline_secret(&table, "") {
        Some(path) => Err(format!(
            "inline secret `{path}` refused: give the key as a file through `{field}` (ADR 0016)"
        )),
        None => Ok(()),
    }
}

fn check_metrics(metrics: &Option<MetricsSection>) -> Result<(), String> {
    if metrics
        .as_ref()
        .is_some_and(|m| !m.listen.ip().is_loopback())
    {
        return Err("metrics.listen must be a loopback address".into());
    }
    Ok(())
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FirewallSection {
    /// Bound of the UDP flow and fragment table (spec §15).
    #[serde(default = "default_udp_flows_max")]
    pub udp_flows_max: usize,
}

impl Default for FirewallSection {
    fn default() -> Self {
        Self {
            udp_flows_max: default_udp_flows_max(),
        }
    }
}

fn default_udp_flows_max() -> usize {
    UDP_FLOWS_MAX
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LogSection {
    /// A `tracing` filter (`info`, `kekkai_io=debug,info`); `RUST_LOG` overrides it.
    #[serde(default = "default_level")]
    pub level: String,
}

impl Default for LogSection {
    fn default() -> Self {
        Self {
            level: default_level(),
        }
    }
}

fn default_listen_port() -> u16 {
    DEFAULT_LISTEN_PORT
}

fn default_mtu() -> u16 {
    kekkai_core::MTU as u16
}

fn default_level() -> String {
    "info".into()
}

impl NodeConfig {
    /// Parses and validates a node file: what `kekkai-node config check` runs.
    pub fn parse(text: &str) -> Result<Self, String> {
        refuse_inline_secret(text, "node.private_key_file")?;
        let config: Self = toml::from_str(text).map_err(|e| e.to_string())?;
        config.validate()?;
        Ok(config)
    }

    fn validate(&self) -> Result<(), String> {
        let node = &self.node;
        if self.firewall.udp_flows_max == 0 {
            return Err("firewall.udp_flows_max must not be 0".into());
        }
        check_metrics(&self.metrics)?;
        if node.listen_port == 0 {
            return Err("node.listen_port must not be 0".into());
        }
        if !(MIN_MTU..=kekkai_core::MTU as u16).contains(&node.mtu) {
            return Err(format!(
                "node.mtu must be between {MIN_MTU} and {} (ADR 0009)",
                kekkai_core::MTU
            ));
        }
        let mut addresses = HashSet::new();
        for a in &node.addresses {
            if !addresses.insert(host_address(a)?) {
                return Err(format!("address {a} appears twice"));
            }
        }
        // ADR 0010: one IPv4 /32 and one IPv6 /128 per node.
        let v4 = addresses.iter().filter(|a| a.is_ipv4()).count();
        if v4 > 1 || addresses.len() - v4 > 1 {
            return Err("node.addresses: at most one IPv4 and one IPv6 address".into());
        }
        let mut keys = HashSet::new();
        let mut names = HashSet::new();
        for peer in &self.peers {
            if peer.name.is_empty() || !names.insert(peer.name.as_str()) {
                return Err(format!("peer name `{}` is empty or repeated", peer.name));
            }
            let key = peer.key()?;
            if !keys.insert(key) {
                return Err(format!("peer {}: public key repeated", peer.name));
            }
            for a in &peer.addresses {
                if !addresses.insert(host_address(a)?) {
                    return Err(format!("peer {}: address {a} appears twice", peer.name));
                }
            }
            for e in &peer.endpoints {
                endpoint(e).map_err(|err| format!("peer {}: {err}", peer.name))?;
            }
            peer.rules()?;
        }
        // ADR 0012: lighthouses are a list, v0 supports one element.
        if self.lighthouses.len() > 1 {
            return Err("lighthouses: v0 supports a single lighthouse".into());
        }
        for l in &self.lighthouses {
            if !keys.insert(l.key()?) {
                return Err("a lighthouse key is also a peer key (spec §10.2)".into());
            }
            endpoint(&l.endpoint).map_err(|err| format!("lighthouse: {err}"))?;
        }
        // ADR 0014: relays are a list, v0 supports one element.
        if self.relays.len() > 1 {
            return Err("relays: v0 supports a single relay".into());
        }
        for r in &self.relays {
            if !keys.insert(r.key()?) {
                return Err("a relay key is also a peer or lighthouse key (spec §10.2)".into());
            }
            endpoint(&r.endpoint).map_err(|err| format!("relay: {err}"))?;
        }
        // Linux disables IPv6 on an interface whose MTU is below 1280.
        if node.mtu < 1280 && addresses.iter().any(IpAddr::is_ipv6) {
            return Err("node.mtu below 1280 leaves no IPv6 on the interface".into());
        }
        // log.level is checked by the daemon, which owns the tracing subscriber.
        Ok(())
    }

    /// The node's own overlay addresses, validated by [`NodeConfig::parse`].
    pub fn addresses(&self) -> Vec<IpAddr> {
        let parse = |a: &String| host_address(a).expect("validated");
        self.node.addresses.iter().map(parse).collect()
    }
}

impl PeerSection {
    pub fn key(&self) -> Result<PublicKey, String> {
        public_key_from_text(&self.public_key)
            .ok_or_else(|| format!("peer {}: public_key is not a base64 32-byte key", self.name))
    }

    /// The peer's `allow_inbound` rules.
    pub fn rules(&self) -> Result<Vec<Rule>, String> {
        let parse = |r: &String| r.parse().map_err(|e| format!("peer {}: {e}", self.name));
        self.allow_inbound.iter().map(parse).collect()
    }

    /// The peer's overlay addresses, validated by [`NodeConfig::parse`].
    pub fn host_addresses(&self) -> Vec<IpAddr> {
        let parse = |a: &String| host_address(a).expect("validated");
        self.addresses.iter().map(parse).collect()
    }
}

/// `10.1.2.3/32` or `fd00::1/128` (ADR 0010: host routes only in v0).
pub fn host_address(text: &str) -> Result<IpAddr, String> {
    let (ip, len) = text
        .split_once('/')
        .ok_or_else(|| format!("address {text}: missing prefix length"))?;
    let ip: IpAddr = ip
        .parse()
        .map_err(|_| format!("address {text}: not an IP address"))?;
    let full = if ip.is_ipv4() { "32" } else { "128" };
    if len != full {
        return Err(format!("address {text}: only /{full} is accepted in v0"));
    }
    Ok(ip)
}

/// `host:port` or `[v6]:port`; the host is resolved by the IO layer.
pub fn endpoint(text: &str) -> Result<(&str, u16), String> {
    let (host, port) = text
        .rsplit_once(':')
        .ok_or_else(|| format!("endpoint {text}: expected host:port"))?;
    let port: u16 = port
        .parse()
        .ok()
        .filter(|p| *p != 0)
        .ok_or_else(|| format!("endpoint {text}: bad port"))?;
    let host = host
        .strip_prefix('[')
        .and_then(|h| h.strip_suffix(']'))
        .unwrap_or(host);
    if host.is_empty() {
        return Err(format!("endpoint {text}: empty host"));
    }
    Ok((host, port))
}

/// The dotted path of the first `private_key` key anywhere in the document.
fn inline_secret(table: &toml::Table, prefix: &str) -> Option<String> {
    table.iter().find_map(|(key, value)| {
        let path = format!("{prefix}{key}");
        if key == "private_key" {
            return Some(path);
        }
        let nested = |t: &toml::Table| inline_secret(t, &format!("{path}."));
        match value {
            toml::Value::Table(t) => nested(t),
            toml::Value::Array(items) => items.iter().find_map(|v| v.as_table().and_then(nested)),
            _ => None,
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const PUB_A: &str = "hSDwCYkwp1R0i33ctD73Wg2/Og0mOBr066SpjqqbTmo=";
    const PUB_B: &str = "3p7bfXt9wbTTW2HC7OQ1Nz+DQ8hbeGdNrfx+FG+IK08=";

    /// ADR 0016's example, restricted to the v0.3 schema.
    const EXAMPLE: &str = r#"
[node]
private_key_file = "/run/secrets/kekkai-key"
listen_port = 4802
addresses = ["10.0.0.1/32", "fd00::1/128"]
mtu = 1280

[[peers]]
name = "a"
public_key = "hSDwCYkwp1R0i33ctD73Wg2/Og0mOBr066SpjqqbTmo="
addresses = ["10.0.0.2/32", "fd00::2/128"]
endpoints = ["a.example.org:4802", "[2001:db8::2]:4802", "192.0.2.2:4802"]
allow_inbound = ["tcp/22", "udp/53", "tcp/*", "any"]

[[peers]]
name = "b"
public_key = "3p7bfXt9wbTTW2HC7OQ1Nz+DQ8hbeGdNrfx+FG+IK08="
addresses = ["10.0.0.3/32"]

[[lighthouses]]
public_key = "ta5DN5JdcLfn//qzn1vkBX+LgBEF698PsB10l9cpxxo="
endpoint = "lighthouse.example.org:4800"

[[relays]]
public_key = "HZekfj15ogjJcYSkT1dubjBB7Twk+3P6/n+fHFl14Ho="
endpoint = "relay.example.org:4801"

[firewall]
udp_flows_max = 128

[log]
level = "info"
"#;

    #[test]
    fn complete_example() {
        let c = NodeConfig::parse(EXAMPLE).unwrap();
        assert_eq!(c.node.listen_port, 4802);
        assert_eq!(c.peers.len(), 2);
        assert_eq!(
            c.peers[0].key().unwrap(),
            public_key_from_text(PUB_A).unwrap()
        );
        assert_eq!(
            c.peers[1].key().unwrap(),
            public_key_from_text(PUB_B).unwrap()
        );
        assert_eq!(c.addresses()[1], "fd00::1".parse::<IpAddr>().unwrap());
        let rules: Vec<String> = c.peers[0]
            .rules()
            .unwrap()
            .iter()
            .map(|r| r.to_string())
            .collect();
        assert_eq!(rules, c.peers[0].allow_inbound);
        assert!(c.peers[1].rules().unwrap().is_empty(), "default deny");
        assert_eq!(c.firewall.udp_flows_max, 128);
        assert_eq!(
            endpoint(&c.peers[0].endpoints[1]).unwrap(),
            ("2001:db8::2", 4802)
        );
        assert_eq!(c.lighthouses.len(), 1);
        assert!(c.lighthouses[0].key().is_ok());
        assert_eq!(c.relays.len(), 1);
        assert_eq!(c.relays[0].endpoint, "relay.example.org:4801");
    }

    #[test]
    fn relays() {
        const PUB_C: &str = "ta5DN5JdcLfn//qzn1vkBX+LgBEF698PsB10l9cpxxo=";
        const PUB_D: &str = "HZekfj15ogjJcYSkT1dubjBB7Twk+3P6/n+fHFl14Ho=";
        let base = format!(
            "[node]\nprivate_key_file = \"/k\"\naddresses = [\"10.0.0.1/32\"]\n\
             [[peers]]\nname = \"a\"\npublic_key = \"{PUB_A}\"\naddresses = []\n\
             [[lighthouses]]\npublic_key = \"{PUB_C}\"\nendpoint = \"192.0.2.1:4800\"\n"
        );
        let one = |key: &str, endpoint: &str| {
            format!("[[relays]]\npublic_key = \"{key}\"\nendpoint = \"{endpoint}\"\n")
        };
        let ok = format!("{base}{}", one(PUB_D, "192.0.2.1:4801"));
        assert!(NodeConfig::parse(&ok).is_ok());
        let two = format!("{ok}{}", one(PUB_B, "192.0.2.2:4801"));
        assert!(
            NodeConfig::parse(&two)
                .unwrap_err()
                .contains("single relay")
        );
        for key in [PUB_A, PUB_C] {
            let same = format!("{base}{}", one(key, "192.0.2.1:4801"));
            assert!(NodeConfig::parse(&same).unwrap_err().contains("relay key"));
        }
        let port = format!("{base}{}", one(PUB_D, "192.0.2.1"));
        assert!(NodeConfig::parse(&port).unwrap_err().contains("relay:"));
    }

    const RELAY: &str = r#"
[service]
private_key_file = "/run/secrets/kekkai-relay-key"
listen_port = 4801
max_bytes_per_second = 1000000

[[peers]]
name = "a"
public_key = "hSDwCYkwp1R0i33ctD73Wg2/Og0mOBr066SpjqqbTmo="

[[peers]]
name = "b"
public_key = "3p7bfXt9wbTTW2HC7OQ1Nz+DQ8hbeGdNrfx+FG+IK08="

[log]
level = "info"

[metrics]
listen = "127.0.0.1:9482"
"#;

    #[test]
    fn relay_file() {
        let c = RelayConfig::parse(RELAY).unwrap();
        assert_eq!(c.service.max_bytes_per_second, Some(1_000_000));
        assert_eq!(c.peers.len(), 2);
        let d = RelayConfig::parse("[service]\nprivate_key_file = \"/k\"\n").unwrap();
        assert_eq!(
            (d.service.listen_port, d.service.max_bytes_per_second),
            (4801, None)
        );
        for (from, to, want) in [
            ("listen_port = 4801", "private_key = \"x\"", "inline secret"),
            ("listen_port = 4801", "listen_port = 0", "listen_port"),
            ("= 1000000", "= 0", "max_bytes_per_second"),
            ("= 1000000", "= -1", "max_bytes_per_second"),
            ("name = \"b\"", "name = \"a\"", "repeated"),
            ("127.0.0.1:9482", "0.0.0.0:9482", "loopback"),
            ("[log]", "[firewall]", "unknown field"),
        ] {
            let err = RelayConfig::parse(&RELAY.replacen(from, to, 1)).unwrap_err();
            assert!(err.contains(want), "{to}: {err}");
        }
    }

    #[test]
    fn lighthouses() {
        let base = format!(
            "[node]\nprivate_key_file = \"/k\"\naddresses = [\"10.0.0.1/32\"]\n\
             [[peers]]\nname = \"a\"\npublic_key = \"{PUB_A}\"\naddresses = []\n"
        );
        let one = |key: &str, endpoint: &str| {
            format!("[[lighthouses]]\npublic_key = \"{key}\"\nendpoint = \"{endpoint}\"\n")
        };
        let ok = format!("{base}{}", one(PUB_B, "192.0.2.1:4800"));
        assert!(NodeConfig::parse(&ok).is_ok());
        let two = format!("{ok}{}", one(PUB_B, "192.0.2.2:4800"));
        assert!(NodeConfig::parse(&two).unwrap_err().contains("single"));
        let peer = format!("{base}{}", one(PUB_A, "192.0.2.1:4800"));
        assert!(NodeConfig::parse(&peer).unwrap_err().contains("peer key"));
        let port = format!("{base}{}", one(PUB_B, "192.0.2.1"));
        assert!(NodeConfig::parse(&port).unwrap_err().contains("lighthouse"));
    }

    const LIGHTHOUSE: &str = r#"
[service]
private_key_file = "/run/secrets/kekkai-lighthouse-key"
listen_port = 4800

[[peers]]
name = "a"
public_key = "hSDwCYkwp1R0i33ctD73Wg2/Og0mOBr066SpjqqbTmo="

[[peers]]
name = "b"
public_key = "3p7bfXt9wbTTW2HC7OQ1Nz+DQ8hbeGdNrfx+FG+IK08="

[log]
level = "info"

[metrics]
listen = "127.0.0.1:9481"
"#;

    #[test]
    fn lighthouse_file() {
        let c = LighthouseConfig::parse(LIGHTHOUSE).unwrap();
        assert_eq!((c.service.listen_port, c.peers.len()), (4800, 2));
        assert_eq!(
            c.peers[1].key().unwrap(),
            public_key_from_text(PUB_B).unwrap()
        );
        let d = LighthouseConfig::parse("[service]\nprivate_key_file = \"/k\"\n").unwrap();
        assert_eq!(d.service.listen_port, 4800);
        let refused = [
            ("private_key = \"x\"", "inline secret `service.private_key`"),
            ("listen_port = 0", "listen_port"),
        ];
        for (extra, want) in refused {
            let text = LIGHTHOUSE.replacen("[service]\n", &format!("[service]\n{extra}\n"), 1);
            let err = LighthouseConfig::parse(&text).unwrap_err();
            assert!(err.contains(want), "{extra}: {err}");
        }
        for (from, to, want) in [
            ("name = \"b\"", "name = \"a\"", "repeated"),
            (PUB_B, PUB_A, "repeated"),
            (PUB_B, "AAAA", "public_key"),
            ("127.0.0.1:9481", "0.0.0.0:9481", "loopback"),
            (
                "[[peers]]\nname = \"b\"",
                "[[peers]]\naddresses = []\nname = \"b\"",
                "unknown field",
            ),
        ] {
            let err = LighthouseConfig::parse(&LIGHTHOUSE.replacen(from, to, 1)).unwrap_err();
            assert!(err.contains(want), "{to}: {err}");
        }
    }

    #[test]
    fn defaults() {
        let c =
            NodeConfig::parse("[node]\nprivate_key_file = \"/k\"\naddresses = [\"10.0.0.1/32\"]\n")
                .unwrap();
        assert_eq!((c.node.listen_port, c.node.mtu), (4802, 1280));
        assert_eq!(c.log.level, "info");
        assert_eq!(c.firewall.udp_flows_max, 4096);
        assert!(c.peers.is_empty());
    }

    #[test]
    fn refusals() {
        let refused = [
            // Inline secrets, wherever they are.
            ("private_key = \"x\"", "inline secret `node.private_key`"),
            (
                "[[peers]]\nprivate_key = \"x\"",
                "inline secret `peers.private_key`",
            ),
            // Typos.
            ("[[relay]]\npublic_key = \"x\"", "unknown field"),
            ("mtu = 1400", "node.mtu"),
            ("mtu = 100", "node.mtu"),
            ("listen_port = 0", "listen_port"),
        ];
        let base = "[node]\nprivate_key_file = \"/k\"\naddresses = [\"10.0.0.1/32\"]\n";
        for (extra, want) in refused {
            // Lines for [node] go right after its header; the others after the section.
            let text = if extra.starts_with('[') {
                format!("{base}{extra}\n")
            } else {
                base.replacen("[node]\n", &format!("[node]\n{extra}\n"), 1)
            };
            let err = NodeConfig::parse(&text).unwrap_err();
            assert!(err.contains(want), "{extra}: {err}");
        }
        let two = base.replace("\"10.0.0.1/32\"", "\"10.0.0.1/32\", \"10.0.0.2/32\"");
        assert!(NodeConfig::parse(&two).unwrap_err().contains("at most one"));
        let low = base.replace("[node]\n", "[node]\nmtu = 1200\n");
        assert!(
            NodeConfig::parse(&low).is_ok(),
            "IPv4 only: a lower MTU is fine"
        );
        let low6 = low.replace("10.0.0.1/32", "fd00::1/128");
        assert!(NodeConfig::parse(&low6).unwrap_err().contains("IPv6"));
        for bad in ["10.0.0.0/24", "fd00::/64", "10.0.0.1", "nope/32"] {
            let text = base.replace("10.0.0.1/32", bad);
            assert!(NodeConfig::parse(&text).is_err(), "{bad}");
        }
        let dup = format!(
            "{base}[[peers]]\nname = \"a\"\npublic_key = \"{PUB_A}\"\naddresses = [\"10.0.0.1/32\"]\n"
        );
        assert!(NodeConfig::parse(&dup).unwrap_err().contains("twice"));
        let bad_key =
            format!("{base}[[peers]]\nname = \"a\"\npublic_key = \"AAAA\"\naddresses = []\n");
        assert!(
            NodeConfig::parse(&bad_key)
                .unwrap_err()
                .contains("public_key")
        );
        for rule in [
            "tcp",
            "tcp/0",
            "tcp/65536",
            "icmp/1",
            "udp/",
            "ANY",
            "tcp/22-23",
        ] {
            let text = format!(
                "{base}[[peers]]\nname = \"a\"\npublic_key = \"{PUB_A}\"\naddresses = []\n\
                 allow_inbound = [\"{rule}\"]\n"
            );
            let err = NodeConfig::parse(&text).unwrap_err();
            assert!(err.contains("peer a: rule"), "{rule}: {err}");
        }
        let open = format!("{base}[metrics]\nlisten = \"0.0.0.0:9100\"\n");
        assert!(NodeConfig::parse(&open).unwrap_err().contains("loopback"));
        let local = format!("{base}[metrics]\nlisten = \"[::1]:9100\"\n");
        assert_eq!(
            NodeConfig::parse(&local)
                .unwrap()
                .metrics
                .unwrap()
                .listen
                .port(),
            9100
        );
        let zero = format!("{base}[firewall]\nudp_flows_max = 0\n");
        assert!(
            NodeConfig::parse(&zero)
                .unwrap_err()
                .contains("udp_flows_max")
        );
        for e in ["host", "host:0", ":4802", "host:x"] {
            assert!(endpoint(e).is_err(), "{e}");
        }
    }
}
